function rollDice(again){if(!G||busy||phase!=='roll'||G.over)return;busy=true;render();const d=$('#die');d.classList.add('roll');Snd.play('roll');return(async()=>{const spins=S.instant?1:6,delay=S.instant?35:80*S.speed;for(let k=0;k<spins;k++){face(1+Math.floor(Math.random()*6));await sleep(delay)}d.classList.remove('roll');const c=cur(),r=Dice.roll(G,c);if(G.mx&&G.mx.chaos&&(!G.matchPower||G.matchPower[c]!=='bad')&&Math.random()<.125){busy=false;return wild(c)}return settle(c,r,again)})()}
async function settle(c,r,again){G.roll=r;if(r===6)Snd.play('six');face(r);G.sixes=r===6?G.sixes+1:0;if(O.rules.three6&&G.sixes>=3){say('Three 6s in a row - turn lost');busy=false;render();await sleep(900);return after(false)}const l=Rules.legal(G,c,r);busy=false;if(!l.length){const hasReroll=G.cards&&Array.isArray(G.cards[c])&&G.cards[c].includes('reroll');say(NAMES[c]+' rolled '+r+' - no move'+(!isBot(c)&&hasReroll?' · Re-roll available':''));render();if(isBot(c)&&typeof botMaybeReroll==='function'&&botMaybeReroll(c,r,{i:null}))return;await sleep((hasReroll&&!isBot(c)?2200:900)*S.speed);if(!G||G.over||cur()!==c||G.roll!==r)return;if(G.mx&&G.mx.helper&&G.mx.helper[c]&&!again&&!G.over){say(NAMES[c]+': helper re-roll');await sleep(500*S.speed);if(r===6)G.sixes--;G.roll=null;return rollDice(true)}return after(false)}phase='move';say(NAMES[c]+' rolled '+r+(isBot(c)?'':' - tap a glowing token'));saveG();render();if(isBot(c))botPick()}
function wild(c){G.roll=null;phase='pick';busy=false;Snd.play('six');say(NAMES[c]+' rolled a wild star - choose 1 to 6');render();if(isBot(c))setTimeout(()=>{if(G&&phase==='pick'&&cur()===c)pickVal(botWild(c))},800*S.speed)}
function pickVal(v){if(!G||phase!=='pick')return;busy=true;phase='roll';settle(cur(),v,false)}
function onTok(c,i){if(!G)return;if(Tap.handle(c,i))return;if(busy||isBot(c)||phase!=='move'||c!==cur()||!Rules.legal(G,c,G.roll).includes(i))return;G_move(c,i)}
async function G_move(c,i){if(busy||phase!=='move')return;busy=true;phase='wait';const r=G.roll,old=G.pos[c][i],np=Rules.dest(old,r);if(np===null){busy=false;phase='move';return}Undo.push();render();if(old<0){G.pos[c][i]=0;Snd.play('move');render();await sleep(220*S.speed)}else for(let p=old+1;p<=np;p++){G.pos[c][i]=p;Snd.play('move');render();await sleep(140*S.speed)}let extra=r===6;const caps=Rules.captures(G,c,np);if(caps.length){Snd.play('cap');buzz(80);caps.forEach(([o,k])=>{T[o+k].classList.add('hit');G.pos[o][k]=-1});if(O.rules.capExtra)extra=true;captureCard(c);await sleep(350*S.speed);render();Object.values(T).forEach(t=>t.classList.remove('hit'))}if(np===56){Snd.play('home');extra=true}if(G.pos[c].every(p=>p===56)&&!G.ranks.includes(c)){G.ranks.push(c);say(NAMES[c]+' finished #'+G.ranks.length)}const left=G.cols.filter(x=>!G.ranks.includes(x));if(left.length<=1){if(left[0])G.ranks.push(left[0]);G.over=true;rec(c,r);saveG();render();return over()}rec(c,r);busy=false;after(extra)}
function after(extra){const c=cur();G.roll=null;if(G.ranks.includes(c))extra=false;if(!extra){G.sixes=0;const nx=()=>{do G.turn=(G.turn+1)%G.cols.length;while(G.ranks.includes(cur()))};nx();if(G.skip&&G.skip===cur()){toast(NAMES[cur()]+' skips a turn');G.skip=null;nx()}if(G.shield)delete G.shield[cur()];G.tc=(G.tc||0)+1;if(G.peace>0)G.peace--;hostTick()}phase='roll';busy=false;saveG();say(NAMES[cur()]+(extra?' rolls again':' to roll')+(G.peace>0?' - peace: no captures ('+G.peace+')':''));render();botTurn()}
const threat=(c,p)=>{const cl=Rules.cell(c,p);if(cl<0)return false;for(const o of G.cols)if(o!==c)for(const q of G.pos[o]){if(q<0||q>50)continue;const d=(cl-Rules.cell(o,q)+52)%52;if(d>=1&&d<=6)return true}return false};
function botBest(c,r){const l=Rules.legal(G,c,r),hard=O.diff==='hard';let best=null,bs=-1e9;l.forEach(i=>{const p=G.pos[c][i],np=Rules.dest(p,r),cl=Rules.cell(c,np);let sc=np/56*(hard?18:10);if(p<0)sc+=50;if(np===56)sc+=80;if(Rules.captures(G,c,np).length)sc+=100;if(np>50||(cl>=0&&SAFE.has(cl)))sc+=25;if(p>=0&&p<=50&&!SAFE.has(Rules.cell(c,p))&&threat(c,p))sc+=hard?45:30;if(cl>=0&&!SAFE.has(cl)&&threat(c,np))sc-=hard?55:35;sc+=Math.random();if(sc>bs){bs=sc;best=i}});return{i:best,s:bs,l}}
function botPick(){const c=cur(),r=G.roll,b=botBest(c,r);if(b.i===null)return;if(typeof botMaybeReroll==='function'&&botMaybeReroll(c,r,b))return;let i=b.i;if(O.diff==='easy'&&Math.random()<.6)i=b.l[Math.floor(Math.random()*b.l.length)];setTimeout(()=>{if(G&&!G.over&&cur()===c&&phase==='move'&&$('#game').classList.contains('on'))G_move(c,i)},650*S.speed)}
function botWild(c){let v=6,bs=-1e9;for(let x=1;x<=6;x++){const b=botBest(c,x);if(b.i!==null&&b.s>bs){bs=b.s;v=x}}return v}
function botTurn(){if(!G||G.over||!isBot(cur())||phase!=='roll')return;setTimeout(()=>{if(G&&!G.over&&isBot(cur())&&phase==='roll'&&!busy&&$('#game').classList.contains('on')){botCards(cur());doRoll()}},750*S.speed)}
$('#die').onclick=()=>{if(G&&!isBot(cur()))doRoll()};
const Stats={get:()=>Object.assign({games:0,wins:{}},Store.get('ldb_stats',{})),add(c){const st=this.get();st.games++;st.wins[c]=(st.wins[c]||0)+1;Store.set('ldb_stats',st)}};
function showStats(){const st=Stats.get(),el=$('#stats');el.textContent=st.games?st.games+' games played · '+Object.entries(st.wins).sort((a,b)=>b[1]-a[1]).map(([c,n])=>NAMES[c]+' '+n).join(' · '):''}
function confetti(){const box=$('#confetti');box.innerHTML='';for(let i=0;i<70;i++){const e=document.createElement('i');e.style.cssText='left:'+Math.random()*100+'%;background:'+HEX[COLORS[i%4]]+';animation-delay:'+Math.random()*.8+'s;animation-duration:'+(2+Math.random()*1.6)+'s;transform:rotate('+Math.random()*360+'deg)';box.appendChild(e)}box.classList.add('on');setTimeout(()=>box.classList.remove('on'),4200)}
function over(){Stats.add(G.ranks[0]);saveReplay();confetti();Snd.music(0);Snd.play('win');buzz(200);$('#ranks').innerHTML=G.ranks.map((c,i)=>'<li style="--c:'+HEX[c]+'"><span>'+(['🥇','🥈','🥉','4️⃣'][i]||'')+'</span><b>'+NAMES[c]+'</b></li>').join('');modal('#mOver');Store.del('ldb_game')}
