let shakeLast=0,shakeMag=0;addEventListener('devicemotion',e=>{if(!S.shake||!G||G.over||busy||phase!=='roll'||isBot(cur())||!$('#game').classList.contains('on'))return;const a=e.accelerationIncludingGravity||e.acceleration;if(!a)return;const mag=Math.hypot(+a.x||0,+a.y||0,+a.z||0),now=Date.now(),delta=Math.abs(mag-shakeMag);shakeMag=mag;if(delta>12&&now-shakeLast>1200){shakeLast=now;buzz(35);doRoll()}},{passive:true});
